var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var manager=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t=>t.gameObject).First(g=>g.name=="Pickup_Pool_Manager").GetComponent<SoulHunter.Gameplay.Pickups.PickupPoolManager>();var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>("Assets/Prefabs/Items/SH10_TimeFreeze.prefab");if(!prefab)throw new System.Exception("Missing SH10_TimeFreeze prefab");var so=new UnityEditor.SerializedObject(manager);var p=so.FindProperty("_timeFreezePrefab");if(p==null)throw new System.Exception("PickupPoolManager time-freeze field missing");p.objectReferenceValue=prefab;so.ApplyModifiedPropertiesWithoutUndo();UnityEditor.AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);return new{scene=scene.path,assigned=prefab.name};
